import React, { ReactNode } from 'react';
import { isElement } from 'react-is';

import { ChartToolbar } from '../../core/slots/toolbar/ChartToolbar.js';
import { DEFAULT_LEGEND_POSITION } from '../constants.js';
import { HoneycombLegend } from '../slots/HoneycombLegend.js';
import { HoneycombSlotsConfig } from '../types/honeycomb-internal.js';

export const iterateHoneycombSlots = (children: ReactNode) => {
  let config: HoneycombSlotsConfig = { legend: undefined, toolbar: undefined };
  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case HoneycombLegend: {
          config = {
            ...config,
            legend: {
              position: DEFAULT_LEGEND_POSITION,
              ...child.props,
            },
          };
          break;
        }
        case ChartToolbar: {
          const { children, ...toolbar } = child.props;
          const childrenToolbar = iterateChartToolbarSlots(children);

          config = {
            ...config,
            toolbar: {
              ...toolbar,
              ...childrenToolbar,
            },
          };
          break;
        }
      }
    }
  });

  return config;
};

/**
 * Generates chart toolbar config based on slots
 * @param children - ChartToolbar children
 * @returns ChartToolbar slot config
 */
const iterateChartToolbarSlots = (children: React.ReactElement[]) => {
  let toolbar = {};

  React.Children.forEach(children, (childToolbar) => {
    if (
      isElement(childToolbar) &&
      childToolbar.type === ChartToolbar.DownloadData
    ) {
      toolbar = {
        ...toolbar,
        downloadData: { enabled: true },
      };
    }
  });

  return toolbar;
};
